 "DESC": {
  "Nguyên âm (Hangul)": "10 nguyên âm cơ bản: đọc được chúng là bạn đánh vần được mọi từ. Trong phiên âm Latinh, o = “ô”; eo gần “ơ”, môi không tròn; eu = “ư”; ae và e là một âm, giữa “e” và “ê”.",
  "Phụ âm (Hangul)": "14 phụ âm cơ bản và cách chúng đổi âm ở cuối âm tiết. Trong phiên âm Latinh, k, t, p, ch bật hơi mạnh như “th”, không phải “kh” hay “ph”; g, d, b, j nhẹ: d không phải “d” tiếng Việt, j là “ch” nhẹ; r là chạm nhẹ đầu lưỡi một lần, cuối âm tiết là l, đừng đọc thành “n”; s = “x”.",
  "Nâng cao (Hangul)": "Phụ âm căng và bật hơi, nguyên âm ghép, phụ âm cuối kép. Trong phiên âm Latinh, kk, tt, pp, jj, ss căng và ngắn như “c, t, p, ch, x” tiếng Việt, không kéo dài; wa, wo, wi = “oa, uơ, uy”; oe = “uê”; ui = “ưi”.",
  "Mẹo phát âm": "Các quy tắc biến âm khiến lời nói thật khác với chữ viết. Tiếng Hàn không có thanh điệu, và phụ âm cuối nối sang âm tiết sau mà không ngắt hơi.",
  "Câu sinh tồn": "12 câu giúp bạn xoay xở trọn một ngày ở Hàn Quốc.",
  "Giới thiệu bản thân": "Tên, quê quán, tuổi, công việc, sở thích: kịch bản cho lần gặp đầu tiên.",
  "Câu sinh tồn 2": "Nhờ giúp đỡ, nhờ nói lại, trả tiền, tìm đường khi bị lạc.",
  "Hỏi chỗ, hỏi đường": "Nhà vệ sinh, lối ra, chỗ ngồi, wifi, giờ mở cửa: mọi câu hỏi “… ở đâu?”.",
  "Quán cà phê & cửa hàng tiện lợi": "Cỡ cốc, nóng hay đá, thẻ tích điểm, hâm nóng đồ ăn, túi đựng.",
  "Con số ngoài đời": "Giá tiền, số điện thoại, số tầng và giờ giấc như người ta viết thật.",
  "Đơn vị đếm": "Cách đếm đồ vật, người, cốc, chai, con vật. Giống “hai cốc cà phê” trong tiếng Việt, nhưng số và đơn vị đếm đứng sau danh từ.",
  "Thời tiết & cảm xúc": "Chuyện thời tiết và cảm xúc của bạn: hai cách mở lời phổ biến nhất.",
  "Từ nối": "Và, nên, nhưng, rồi: chất keo để kể một câu chuyện.",
  "Bác sĩ & hiệu thuốc": "Triệu chứng, thuốc, dị ứng, đơn thuốc.",
  "Nhà ở & việc vặt": "Tiền thuê, tiền đặt cọc, bưu kiện, phân loại rác, giặt giũ.",
  "Kính ngữ": "Tôn trọng chủ ngữ: 드시다, 주무시다, 계시다 và -(으)시-.",
  "Địa điểm & tòa nhà": "Quán cà phê, phòng gym, thư viện, bảo tàng, nhà: những nơi bạn nói mình sẽ đến.",
  "Sở thích": "Trả lời câu 취미가 뭐예요? bằng những từ thật sự dùng.",
  "Món ăn": "Các món và nguyên liệu có trong mọi thực đơn.",
  "Đồ uống": "Cà phê, trà, soju, bia, và cách gọi thêm một cốc.",
  "Hoạt động": "Động từ hằng ngày kiểu “tôi làm X”, ở dạng lịch sự.",
  "Phim ảnh & giải trí": "Phim truyền hình, chương trình giải trí, thể loại, tập phim, cày phim.",
  "Vị trí & phương hướng": "Trên, bên cạnh, đối diện, lối ra và tầng: để đặt đồ vật và tìm chúng.",
  "Động từ cơ bản": "12 động từ bạn sẽ dùng mỗi ngày, ở dạng lịch sự.",
  "Trợ từ": "Những từ nhỏ đánh dấu chủ đề, chủ ngữ, tân ngữ và nơi chốn. Tiếng Việt đặt giới từ trước (ở nhà); tiếng Hàn đặt trợ từ sau danh từ.",
  "Số": "Số thuần Hàn và số Hán Hàn, và khi nào dùng loại nào.",
  "Lời ngọt ngào": "Dễ thương, xinh, nhớ: dành cho người thân thiết với bạn.",
  "Câu nói dễ thương": "Những lời khen và lời quan tâm chạm đến tim.",
  "Tán tỉnh": "Xin số điện thoại, rủ đi chơi, nói ra cảm xúc.",
  "Nhắn tin thân mật": "Kiểu viết tắt trên KakaoTalk và những câu bạn bè thật sự nhắn cho nhau.",
  "Khen & cổ vũ": "Lời khen, lời động viên và tiếng lóng giữa bạn bè.",
  "Đi chơi": "Rủ rê, hẹn ở đâu và lúc mấy giờ, kết thúc buổi đi chơi.",
  "K-pop & văn hóa fan": "Từ vựng của fandom, từ 최애 đến 떼창.",
  "Mạng xã hội & tiếng lóng": "Instagram, meme và tiếng lóng đang thịnh hành.",
  "Hẹn hò nghiêm túc": "Xác định mối quan hệ, lời khen thật lòng, xin lỗi, trấn an.",
  "Công việc & văn phòng": "Họp, hạn chót, nhờ đồng nghiệp, tan làm đúng giờ, 회식.",
  "Chuyện phiếm": "Hỏi han tình hình, thời tiết, kế hoạch cuối tuần, chào tạm biệt cho đúng cách.",
  "Gọi món": "Gọi món, đơn vị đếm cho đồ ăn, hai câu nói trong bữa ăn.",
  "Chỉ đường & giao thông": "Trái, phải, đi thẳng; những câu dùng khi đi tàu điện ngầm, xe buýt, taxi.",
  "Thời gian & ngày tháng": "Hôm nay, ngày mai, các thứ trong tuần, mấy giờ rồi.",
  "Gia đình & mọi người": "Mẹ, bố, anh chị em, bạn bè, thầy cô, và cách tuổi tác làm đổi từ xưng hô.",
  "Tính từ": "Tốt, tệ, to, nhỏ, nóng, lạnh, bận, vui. Tính từ tiếng Hàn chia đuôi như động từ.",
  "Câu thoại phim Hàn": "Những câu cảm thán và câu thoại bạn sẽ nghe trong mọi tập phim.",
  "Danh từ thông dụng": "Những danh từ tiếng Hàn dùng nhiều nhất mà khóa học chưa dạy, từ thường gặp nhất trở xuống.",
  "Động từ thông dụng": "Động từ chỉ hành động ở dạng nguyên mẫu; phần ghi chú cho dạng 해요 và đánh dấu động từ bất quy tắc.",
  "Tính từ thông dụng": "Tính từ (trong tiếng Hàn, tính từ chia như động từ): dạng 해요 và dạng định ngữ đứng trước danh từ.",
  "Trạng từ thông dụng": "Từ chỉ thời gian, mức độ, tần suất và cách thức: rất, đã, thường, tại sao, thế nào.",
  "Đại từ thông dụng": "Tôi, bạn, cái này, ai, không ai, và vì sao tên hoặc chức danh thường thay cho “bạn”.",
  "Trợ từ mở rộng": "Thứ tiếng Hàn dùng thay giới từ: các trợ từ ngoài chín trợ từ trong bộ thẻ Trợ từ.",
  "Từ nối mở rộng": "Đuôi nối (-고, -지만, -아서, -(으)면 …) gắn trên một động từ, cùng các từ nối chưa có trong bộ thẻ Từ nối.",
  "Từ cảm thán thông dụng": "Những tiếng cảm thán người Hàn thật sự hay thốt ra: oa, ui da, ối, phù, tèn ten, và ai hay nói câu nào.",
  "Từ hữu ích": "Này / đó / nào trước danh từ, các dạng số, ngày và giờ, và các cách nói có và không.",
  "Đơn vị đếm mở rộng": "Các đơn vị đếm chưa có trong bộ thẻ Đơn vị đếm: xe cộ, suất ăn, cuộn, lát, phút, tháng.",
  "Từ ngữ tán tỉnh": "Những từ người Hàn dùng khi tán tỉnh, các câu ghép từ chúng, và cách nhận lời hay từ chối một cách tử tế.",
  "Lời khen hằng ngày": "Lời khen hằng ngày về đồ ăn, công việc, nhà cửa và con cái, cùng những cách đáp lại khiêm tốn.",
  "Các quốc gia": "Mọi quốc gia, nước hay được hỏi nhất đứng trước. Tên nước + 에서 왔어요 = tôi đến từ…; + 사람 = quốc tịch; + 어 = ngôn ngữ.",
  "My phrases": "Mọi thứ bạn tự thêm vào."
 },
